ALTER TABLE activities ADD COLUMN source TEXT NOT NULL DEFAULT 'user';
UPDATE activities SET source='customer' WHERE actor_id IS NULL AND action IN ('quotation.accepted','quotation.rejected');
ALTER TABLE jobs ADD COLUMN template_snapshot TEXT;
CREATE TABLE service_templates(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, checklist TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(company_id,id));
CREATE TABLE maintenance_contracts(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, customer_id TEXT NOT NULL, property_id TEXT NOT NULL, template_id TEXT, name TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', frequency TEXT NOT NULL CHECK(frequency IN ('days','months')), interval_count INTEGER NOT NULL CHECK(interval_count>0), anchor_day INTEGER NOT NULL, next_due TEXT NOT NULL, last_due TEXT, lead_days INTEGER NOT NULL DEFAULT 7 CHECK(lead_days BETWEEN 0 AND 90), active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(company_id,id), FOREIGN KEY(company_id,customer_id,property_id) REFERENCES properties(company_id,customer_id,id), FOREIGN KEY(company_id,template_id) REFERENCES service_templates(company_id,id));
CREATE TABLE maintenance_occurrences(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, contract_id TEXT NOT NULL, due_at TEXT NOT NULL, job_id TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(contract_id,due_at), FOREIGN KEY(company_id,contract_id) REFERENCES maintenance_contracts(company_id,id), FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id));
CREATE TABLE followups(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), job_id TEXT, customer_id TEXT, quote_id TEXT, kind TEXT NOT NULL, title TEXT NOT NULL, due_at TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','done','resolved')), note TEXT NOT NULL DEFAULT '', dedupe_key TEXT NOT NULL, automatic INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(company_id,id), UNIQUE(company_id,dedupe_key), FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id), FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id), FOREIGN KEY(company_id,quote_id) REFERENCES quotes(company_id,id));
CREATE TABLE inventory_items(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), sku TEXT NOT NULL, name TEXT NOT NULL, unit TEXT NOT NULL, quantity_milli INTEGER NOT NULL DEFAULT 0 CHECK(quantity_milli>=0), reorder_milli INTEGER NOT NULL DEFAULT 0 CHECK(reorder_milli>=0), unit_cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(unit_cost_cents>=0), archived INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(company_id,id), UNIQUE(company_id,sku));
CREATE TABLE stock_movements(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, item_id TEXT NOT NULL, job_id TEXT, delta_milli INTEGER NOT NULL CHECK(delta_milli<>0), unit_cost_cents INTEGER NOT NULL, reason TEXT NOT NULL, actor_id TEXT REFERENCES users(id), created_at TEXT NOT NULL, FOREIGN KEY(company_id,item_id) REFERENCES inventory_items(company_id,id), FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id));
CREATE TABLE material_usage(company_id TEXT NOT NULL, job_id TEXT NOT NULL, item_id TEXT NOT NULL, quantity_milli INTEGER NOT NULL CHECK(quantity_milli>=0), unit_cost_cents INTEGER NOT NULL, PRIMARY KEY(job_id,item_id), FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id), FOREIGN KEY(company_id,item_id) REFERENCES inventory_items(company_id,id));
CREATE TABLE cost_settings(company_id TEXT PRIMARY KEY REFERENCES companies(id), labour_rate_cents INTEGER CHECK(labour_rate_cents>=0), overhead_cents INTEGER NOT NULL DEFAULT 0 CHECK(overhead_cents>=0), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE job_costs(job_id TEXT PRIMARY KEY, company_id TEXT NOT NULL, labour_rate_cents INTEGER CHECK(labour_rate_cents>=0), overhead_cents INTEGER NOT NULL DEFAULT 0, material_rates TEXT NOT NULL DEFAULT '[]', other_costs TEXT NOT NULL DEFAULT '[]', version INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL, FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id));
CREATE TABLE revenue_entries(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, job_id TEXT NOT NULL, net_cents INTEGER NOT NULL CHECK(net_cents<>0), reference TEXT NOT NULL, recognized_at TEXT NOT NULL, note TEXT NOT NULL, reverses_id TEXT UNIQUE, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(company_id,id), UNIQUE(company_id,reference), FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id), FOREIGN KEY(company_id,reverses_id) REFERENCES revenue_entries(company_id,id));
CREATE TABLE completion_records(job_id TEXT PRIMARY KEY, company_id TEXT NOT NULL, snapshot TEXT NOT NULL, digest TEXT NOT NULL, recorded_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, FOREIGN KEY(company_id,job_id) REFERENCES jobs(company_id,id));
CREATE TABLE notification_settings(company_id TEXT PRIMARY KEY REFERENCES companies(id), email_enabled INTEGER NOT NULL DEFAULT 0, recipient TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE notifications(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, followup_id TEXT, kind TEXT NOT NULL, title TEXT NOT NULL, detail TEXT NOT NULL, dedupe_key TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL, UNIQUE(company_id,id), UNIQUE(company_id,dedupe_key), FOREIGN KEY(company_id,followup_id) REFERENCES followups(company_id,id));
CREATE TABLE notification_outbox(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, notification_id TEXT NOT NULL, recipient TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','processing','retry','accepted','delivered','failed','suppressed')), attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL, lease_until TEXT, lease_token TEXT, provider_id TEXT UNIQUE, error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(notification_id), FOREIGN KEY(company_id,notification_id) REFERENCES notifications(company_id,id));
CREATE TABLE notification_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT, outbox_id TEXT NOT NULL REFERENCES notification_outbox(id), attempt INTEGER NOT NULL, outcome TEXT NOT NULL, error_code TEXT, created_at TEXT NOT NULL);
CREATE TABLE delivery_events(id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, type TEXT NOT NULL, occurred_at TEXT NOT NULL, received_at TEXT NOT NULL);
CREATE TABLE automation_state(id INTEGER PRIMARY KEY CHECK(id=1), lease_token TEXT, lease_until TEXT, last_started TEXT, last_success TEXT, last_error TEXT);
INSERT INTO automation_state(id) VALUES(1);
CREATE INDEX followup_queue ON followups(company_id,state,due_at);
CREATE INDEX reminder_queue ON notification_outbox(state,available_at,lease_until);
CREATE INDEX notification_company ON notifications(company_id,created_at);
CREATE INDEX stock_company ON inventory_items(company_id,archived);
CREATE INDEX revenue_company_date ON revenue_entries(company_id,recognized_at);
CREATE INDEX maintenance_due ON maintenance_contracts(active,next_due);
